module exact_topk_attention (
    input logic clk,rst,
    input logic in_valid,output logic in_ready,
    input logic [31:0] in_query,
    input logic [255:0] in_keys,
    input logic [511:0] in_values,
    input logic [7:0] in_mask,
    input logic [2:0] in_keep,
    output logic out_valid,input logic out_ready,
    output logic out_status,
    output logic [7:0] out_selected,
    output logic [27:0] out_denominator,
    output logic [63:0] out_values
);
localparam logic [6399:0] FRAC={25'd6196149,25'd6220400,25'd6244746,25'd6269188,25'd6293724,25'd6318357,25'd6343087,25'd6367913,25'd6392836,25'd6417857,25'd6442976,25'd6468193,25'd6493509,25'd6518924,25'd6544438,25'd6570052,25'd6595767,25'd6621582,25'd6647498,25'd6673515,25'd6699635,25'd6725856,25'd6752181,25'd6778608,25'd6805139,25'd6831773,25'd6858512,25'd6885356,25'd6912304,25'd6939358,25'd6966518,25'd6993784,25'd7021157,25'd7048637,25'd7076225,25'd7103920,25'd7131724,25'd7159637,25'd7187659,25'd7215791,25'd7244032,25'd7272385,25'd7300848,25'd7329423,25'd7358109,25'd7386908,25'd7415820,25'd7444844,25'd7473983,25'd7503235,25'd7532602,25'd7562084,25'd7591681,25'd7621394,25'd7651223,25'd7681169,25'd7711232,25'd7741413,25'd7771712,25'd7802130,25'd7832667,25'd7863323,25'd7894099,25'd7924996,25'd7956013,25'd7987152,25'd8018413,25'd8049796,25'd8081302,25'd8112932,25'd8144685,25'd8176562,25'd8208564,25'd8240692,25'd8272945,25'd8305324,25'd8337830,25'd8370464,25'd8403225,25'd8436114,25'd8469132,25'd8502279,25'd8535556,25'd8568963,25'd8602501,25'd8636171,25'd8669972,25'd8703905,25'd8737971,25'd8772171,25'd8806504,25'd8840972,25'd8875574,25'd8910312,25'd8945186,25'd8980197,25'd9015344,25'd9050629,25'd9086052,25'd9121614,25'd9157315,25'd9193156,25'd9229137,25'd9265259,25'd9301522,25'd9337927,25'd9374475,25'd9411165,25'd9447999,25'd9484978,25'd9522101,25'd9559370,25'd9596784,25'd9634345,25'd9672052,25'd9709908,25'd9747911,25'd9786063,25'd9824365,25'd9862816,25'd9901418,25'd9940172,25'd9979076,25'd10018133,25'd10057343,25'd10096706,25'd10136224,25'd10175896,25'd10215723,25'd10255706,25'd10295846,25'd10336143,25'd10376597,25'd10417210,25'd10457982,25'd10498913,25'd10540005,25'd10581257,25'd10622671,25'd10664247,25'd10705986,25'd10747888,25'd10789954,25'd10832185,25'd10874581,25'd10917143,25'd10959871,25'd11002767,25'd11045830,25'd11089063,25'd11132464,25'd11176035,25'd11219777,25'd11263690,25'd11307775,25'd11352032,25'd11396463,25'd11441067,25'd11485846,25'd11530801,25'd1157593