localparam logic [424:0] INTEGRAL={25'd2,25'd5,25'd14,25'd38,25'd103,25'd280,25'd762,25'd2070,25'd5628,25'd15299,25'd41587,25'd113044,25'd307285,25'd835288,25'd2270549,25'd6171993,25'd16777216};
function automatic signed [63:0] nearest(input logic signed [63:0] x,d);
    logic signed [63:0] q,r,m;
    begin m=x<0 ? -x:x;q=m/d;r=m-q*d;
        if(2*r>d || (2*r==d && q[0]))q=q+1;
        nearest=x<0 ? -q:q;
    end
endfunction
integer scores[0:7];
logic [7:0] selected;
integer i,j,rank,best,score,maximum,found,delta;
logic [27:0] denominator;
logic signed [63:0] weight,product,sums[0:3];
logic [63:0] values;
always_comb begin
    selected=0;maximum=0;found=0;best=0;score=0;delta=0;
    denominator=0;weight=0;product=0;values=0;
    for(j=0;j<4;j=j+1)sums[j]=0;
    for(i=0;i<8;i=i+1)begin
        scores[i]=0;
        for(j=0;j<4;j=j+1)scores[i]=scores[i]+32'($signed(in_query[j*8+:8]))*32'($signed(in_keys[(4*i+j)*8+:8]));
    end
    for(rank=0;rank<8;rank=rank+1)if(rank<=in_keep)begin
        best=-1;score=0;
        for(i=0;i<8;i=i+1)if(in_mask[i] && !selected[i])begin
            if(best<0 || scores[i]>score)begin best=i;score=scores[i];end
        end
        if(best>=0)begin
            selected[best]=1;if(found==0)maximum=score;found=found+1;
        end
    end
    for(i=0;i<8;i=i+1)if(selected[i])begin
        delta=maximum-scores[i];weight=0;
        if(delta<=4096)begin
            product=64'(INTEGRAL[(delta>>8)*25+:25])*64'(FRAC[(delta&255)*25+:25]);
            weight=nearest(product,16777216);
        end
        denominator=denominator+weight;
        for(j=0;j<4;j=j+1)sums[j]=sums[j]+weight*64'($signed(in_values[(4*i+j)*16+:16]));
    end
    if(denominator!=0)for(j=0;j<4;j=j+1)values[j*16+:16]=nearest(sums[j],64'(denominator));
end
assign in_ready=!out_valid || out_ready;
always_ff @(posedge clk)begin
    if(rst)begin out_valid<=0;out_status<=0;out_selected<=0;out_denominator<=0;out_values<=0;end
    else if(in_ready)begin
        out_valid<=in_valid;out_status<=in_valid && denominator==0;
        out_selected<=in_valid ? selected:0;out_denominator<=in_valid ? denominator:0;out_values<=in_valid ? values:0;
    end
end
endmodule
